import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"五层与四层对照","description":"","frontmatter":{"title":"五层与四层对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/five-vs-four-layer.md","filePath":"cs/five-vs-four-layer.md","lastUpdated":1789023840000}'),p={name:"cs/five-vs-four-layer.md"};function c(_,a,f,B,A,u){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="五层与四层对照" tabindex="-1">五层与四层对照 <a class="header-anchor" href="#五层与四层对照" aria-label="Permalink to &quot;五层与四层对照&quot;">​</a></h1><div class="epigraph"><p>教学用五层把链路与物理拆开；TCP/IP 四层把它们收成「网络接口」。层名是对照表，不是另一套互联网。</p><footer>—— 据 Kurose and Ross 对五层模型；Cerf and Kahn, 1974；RFC 791/793 的职责切分整理</footer></div><p><a href="/cs/layering-e2e">上一课</a>钉死分层与端到端：功能按层放，正确性在真正两端收口。本课不重做 Saltzer 的文件传送例子。缺口是课序马上要进入一跳的帧：读者会同时碰到教材的五层与实现口里的四层。两套名字对不齐，后课 MAC 与 IP 会像两门课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/layering-e2e">分层</a>已经画出应用、传输、网络、链路、物理。主机协议栈与许多教材把链路加物理叫做网络接口（或「链路」一层），于是只数四层。OSI 七层还多出会话与表示。缺口不是再背一张图，而是：<strong>同一份 PDU 在两种数法里落在哪</strong>，以免把「第四层」一会儿说成传输、一会儿说成链路。</p><p><span class="marginnote">四层不取消物理；它只是不单独当一章。五层把 CRC、介质访问与电信号分开讲，方便本栏下一课进帧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照而不是合并。五层：应用 PDU → 传输段/数据报 → 网络分组 → 链路帧 → 物理比特。四层：应用、传输、互联网、网络接口；接口层同时承担成帧与把比特送到介质。RFC 791 的 IP、RFC 793 的 TCP 按四层职责写成「网际 + 传输」；本栏仍用五层上课，因为帧的 FCS 与 MAC 还没有对象。</p>',8)),(e(),n(h,null,{default:t(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIVE%5B%22%E4%BA%94%E5%B1%82%3A%20%E9%93%BE%E8%B7%AF%E4%B8%8E%E7%89%A9%E7%90%86%E5%88%86%E5%BC%80%22%5D%20--%3E%20FRAME%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%B8%A7%E4%B8%8E%20MAC%22%5D%0A%20%20FOUR%5B%22%E5%9B%9B%E5%B1%82%3A%20%E7%BD%91%E7%BB%9C%E6%8E%A5%E5%8F%A3%E5%90%88%E4%B8%80%E5%B1%82%22%5D%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%20IP%20%E8%BD%BD%E8%8D%B7%22%5D%0A%20%20FIVE%20--%3E%20SAME%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是命名约定。后课谈到「链路 PDU」一律指帧；谈到「网络 PDU」指 IP 分组。套接字接到传输，不接到 MAC。端到端论证不依赖数了几层：可靠性仍不能只放在接口层。组成课的 <a href="/cs/io-dma">DMA</a> 进出的是接口缓冲，内容将被解释成帧，然后才是分组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 OSI 会话/表示插进主干，也不把跨层优化（如 QUIC 把传输与安全绑在 UDP 上）提前当反例写完。七层是历史对照；本栏以五层为课序，四层为实现口译。</p><p>后课默认：一跳的名字在链路，跨网的名字在 IP。下一课只补帧与 MAC，不再争论层数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五层与四层是同一栈的两种切法；本栏按五层往下读。</li><li>链路与物理合层不取消成帧，只是合章。</li><li>一跳 PDU 从下一课的帧开始。</li><li>出处：Kurose and Ross；RFC 791；RFC 793；Cerf and Kahn, 1974。</li></ul>',7))])}const m=s(p,[["render",c]]);export{P as __pageData,m as default};
